<script>
const adFormats=@json($adFormats);const displayScreens=@json($displayScreens);let activeCodeTab='js';let activeTagTab='js';let currentTagZoneData=null;
function resolvedZoneType(rawFormat,adType){if(adType==='display_video'||['instream','outstream','rewarded'].includes(rawFormat))return'video';if(rawFormat==='native')return'native';if(rawFormat==='popunder')return'popup';if(rawFormat==='interstitial')return'interstitial';if(rawFormat==='social_bar')return'bannerbox';if(rawFormat==='in_page_push')return'overlay';return'banner';}
function inferAgeGroup(min,max){if(min===null&&max===null)return'';if(max===19)return'under_20';if(min===20&&max===35)return'20_35';if(min===35&&max===45)return'35_45';if(min===46)return'over_45';return'';}
function applyAgePreset(prefix){const select=document.getElementById(prefix+'age_group');const value=select?select.value:'';const minField=document.getElementById(prefix+'target_age_min');const maxField=document.getElementById(prefix+'target_age_max');if(!minField||!maxField)return;const presets={under_20:[null,19],'20_35':[20,35],'35_45':[35,45],over_45:[46,null],'':[null,null]};const preset=presets[value]||[null,null];minField.value=preset[0]??'';maxField.value=preset[1]??'';}
function formatOptions(adType){if(adType==='display_web'&&displayScreens.length){return displayScreens.map((screen)=>({value:screen.dimension,label:screen.label}));}return Object.entries(adFormats[adType]?.sizes||{}).map(([value,label])=>({value,label}));}
function updateZoneTypePills(){const adType=document.getElementById('adTypeSelect').value;const formatSelect=document.getElementById('adFormatSelect');const option=formatSelect.options[formatSelect.selectedIndex];const rawFormat=formatSelect.value;const zoneType=rawFormat?resolvedZoneType(rawFormat,adType):'banner';const label=option&&option.textContent?option.textContent:'Select size to preview';document.getElementById('zoneTypePills').innerHTML=`<span class="rounded-full bg-brand-50 px-3 py-1 font-semibold text-brand-700">${adFormats[adType]?.label||'Ad Type'}</span><span class="rounded-full bg-gray-100 px-3 py-1 font-semibold text-gray-700">${label}</span><span class="rounded-full bg-emerald-50 px-3 py-1 font-semibold text-emerald-700">${zoneType}</span>`;}
