t_min').value||null,target_height_max:document.getElementById('target_height_max').value||null,target_weight_min:document.getElementById('target_weight_min').value||null,target_weight_max:document.getElementById('target_weight_max').value||null,frequency_views:document.getElementById('frequency_views').value||null,auto_reload:document.getElementById('auto_reload').value==='1',reload_time:document.getElementById('reload_time').value||null,content_width_px:document.getElementById('content_width_px').value||null,content_height_px:document.getElementById('content_height_px').value||null,top_offset_px:document.getElementById('top_offset_px').value||null,right_offset_px:document.getElementById('right_offset_px').value||null,z_index_value:document.getElementById('z_index_value').value||null,is_fixed:document.getElementById('is_fixed').value==='1',hide_side:document.getElementById('hide_side').value||'none'})}).then(async(response)=>{const data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to create adblock.');return data;}).then((data)=>{Object.entries(data.codes||{}).forEach(([id,value])=>{if(document.getElementById(id))document.getElementById(id).value=value||'';});switchCodeTab('js');goToWizardStep(3);window.refreshPublisherNotifications?.();}).catch((error)=>showWizardError(error.message));}
function populateEditFormats(selectedSize=''){const adType=document.getElementById('edit_format_id').value;const select=document.getElementById('edit_size_id');select.innerHTML='';formatOptions(adType).forEach((item)=>{const option=document.createElement('option');option.value=item.value;option.textContent=item.label;select.appendChild(option);});if(selectedSize)select.value=selectedSize;}
function toggleEditTargetType(){const isWeb=document.getElementById('edit_choose_type').value==='web';document.getElementById('editSiteWrapper').classList.toggle('hidden',!isWeb);document.getElementById('editAppWrapper').classList.toggle('hidden',isWeb);}
function editZone(id){fetch('/publisher/adblocks/'+id,{headers:{'Accept':'application/json'}}).then((response)=>response.json()).then((data)=>{document.getElementById('edit_choose_type').value=data.choose_type||'web';toggleEditTargetType();document.getElementById('edit_site_id').value=data.site_id||'';document.getElementById('edit_mobile_app_id').value=data.mobile_app_id||'';document.getElementById('edit_format_id').value=data.format_key||'display_web';populateEditFormats(data.size_key||'');document.getElementById('edit_name').value=data.name||'';document.getElementById('edit_floor_price').value=data.floor_price??'0.00';document.getElementById('edit_passback').value=data.passback||'';document.getElementById('edit_image_width').value=data.image_width||'';document.getElementById('edit_image_height').value=data.image_height||'';document.getElementById('edit_html_template').value=data.html_template||'';document.getElementById('edit_custom_css').value=data.custom_css||'';document.getElementById('edit_bg_color').value=data.bg_color||'#ffffff';document.getElementById('edit_sponsored_prefix').value=data.sponsored_prefix||'';document.getElementById('edit_css_path').value=data.css_path||'';document.getElementById('edit_status').value=data.status||'active';document.getElementById('edit_target_gender').value=data.target_gender||'';document.getElementById('edit_target_color').value=data.target_color||'';document.getElementById('edit_target_height_min').value=data.target_height_min||'';document.getElementById('edit_target_height_max').value=data.target_height_max||'';document.getElementById('edit_target_weight_min').value=data.target_weight_min||'';document.getElementById('edit_target_weight_max').value=data.target_weight_max||'';document.getElementById('edit_frequency_views').value=data.frequency_views||'';document.getElementById('edit_auto_reload').value=data.auto_reload?'1':'0';document.getElementById('edit_reload_time').value=data.reload_time||'';document.getElementById('edit_content_width_px').value=data.content_width_px||'';document.getElementById('edit_content_height_px').value=data.content_height_px||'';document.getElementById('edit_top_offset_px').value=data.top_offset_px||'';document.getElementById('edit_right_offset_px').value=data.right_offset_px||'';document.getElementById('edit_z_index_value').value=data.z_index_value||'';document.getElementById('edit_is_fixed').value=data.is_fixed?'1':'0';document.getElementById('edit_hide_side').value=data.hide_side||'none';document.getElementById('edit_target_age_min').value=data.target_age_min||'';document.getElementById('edit_target_age_max').value=data.target_age_max||'';document.getElementById('edit_age_group').value=inferAgeGroup(data.target_age_min,data.target_age_max);document.getElementById('edit_zone_type').value=data.zone_type||resolvedZoneType(data.size_key||'',data.format_key||'display_web');document.getElementById('edit_placement').value=data.placement||'content';document.getElementById('editForm').action='/publisher/adblocks/'+id;document.getElementById('editModal').classList.remove('hidden');});}
document.getElementById('edit_size_id').addEventListener('change',function(){const zoneType=resolvedZoneType(this.value,document.getElementById('edit_format_id').value);document.getElementById('edit_zone_type').value=zoneType;document.getElementById('edit_placement').value=['overlay','popup','interstitial'].includes(zoneType)?zoneType:'content';});
function deleteZone(id){if(!confirm('Delete this adblock?'))return;fetch('/publisher/adblocks/'+id,{method:'DELETE',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=\"csrf-token\"]').content,'Accept':'application/json'}}).then(()=>window.location.reload());}
function switchTagTab(tabId){activeTagTab=tabId;['js','iframe','inline','real','small','box','head','overlay','curl'].forEach((id)=>{document.getElementById('tag-'+id).classList.toggle('hidden',id!==tabId);document.getElementById('tag-tab-'+id).className='rounded-lg border px-3 py-1.5 text-xs font-semibold '+(id===tabId?'border-brand-600 bg-brand-600 text-white':'border-gray-200 text-gray-600 hover:bg-gray-50');});}
function renderTagSummary(targetId,data){const target=document.getElementById(targetId);target.innerHTML='';Object.entries(data||{}).forEach(([label,value])=>{const row=document.createElement('div');row.className='flex items-start justify-between gap-3 border-b border-gray-200/70 pb-2';row.innerHTML=`<dt class="font-medium text-gray-500">${label.replace(/_/g,' ').replace(/\b\w/g,(char)=>char.toUpperCase())}</dt><dd class="text-right text-gray-900">${value??'-'}</dd>`;target.appendChild(row);});}
function populateTagModalForm(editable){document.getElementById('tag_age_group').value=inferAgeGroup(editable.target_age_min,editable.target_age_max);document.getElementById('tag_target_age_min').value=editable.target_age_min??'';document.getElementById('tag_target_age_max').value=editable.target_age_max??'';document.getElementById('tag_target_gender').value=editable.target_gender||'';document.getElementById('tag_target_color').value=editable.target_color||'';document.getElementById('tag_target_height_min').value=editable.target_height_min??'';document.getElementById('tag_target_height_max').value=editable.target_height_max??'';document.getElementById('tag_target_weight_min').value=editable.target_weight_min??'';document.getElementById('tag_target_weight_max').value=editable.target_weight_max??'';document.getElementById('tag_frequency_views').value=editable.frequency_views??'';document.getElementById('tag_auto_reload').value=editable.auto_reload?'1':'0';document.getElementById('tag_reload_time').value=editable.reload_time??'';document.getElementById('tag_content_width_px').value=editable.content_width_px??'';document.getElementById('tag_content_height_px').value=editable.content_height_px??'';document.getElementById('tag_top_offset_px').value=editable.top_offset_px??'';document.getElementById('tag_right_offset_px').value=editable.right_offset_px??'';document.getElementById('tag_z_index_value').value=editable.z_index_value??'';document.getElementById('tag_is_fixed').value=editable.is_fixed?'1':'0';document.getElementById('tag_hide_side').value=editable.hide_side||'none';}
function refreshTagModal(data){currentTagZoneData=data;document.getElementById('tagModalTitle').textContent=data.name||'';Object.entries(data.codes||{}).forEach(([id,value])=>{if(document.getElementById('tag-'+id))document.getElementById('tag-'+id).value=value||'';});populateTagModalForm(data.editable||{});renderTagSummary('tagTargetingSummary',data.targeting||{});renderTagSummary('tagSettingsSummary',data.settings||{});}
function openTagModal(id){document.getElementById('tagSaveMessage').classList.add('hidden');fetch('/publisher/adblocks/'+id+'/tag',{headers:{'Accept':'application/json'}}).then((response)=>response.json()).then((data)=>{refreshTagModal(data);switchTagTab('js');document.getElementById('tagModal').classList.remove('hidden');});}
function saveTagSettings(){if(!currentTagZoneData||!currentTagZoneData.editable)return;applyAgePreset('tag_');const editable=currentTagZoneData.editable;const payload={choose_type:editable.choose_type,site_id:editable.site_id,mobile_app_id:editable.mobile_app_id,name:editable.name,format_id:editable.format_id,size_id:editable.size_id,zone_type:editable.zone_type,placement:editable.placement,floor_price:editable.floor_price,passback:editable.passback,image_width:editable.image_width,image_height:editable.image_height,html_template:editable.html_template,custom_css:editable.custom_css,bg_color:editable.bg_color,sponsored_prefix:editable.sponsored_prefix,css_path:editable.css_path,inline_video:editable.inline_video,status:editable.status,target_age_min:document.getElementById('tag_target_age_min').value||null,target_age_max:document.getElementById('tag_target_age_max').value||null,target_gender:document.getElementById('tag_target_gender').value||null,target_color:document.getElementById('tag_target_color').value||null,target_height_min:document.getElementById('tag_target_height_min').value||null,target_height_max:document.getElementById('tag_target_height_max').value||null,target_weight_min:document.getElementById('tag_target_weight_min').value||null,target_weight_max:document.getElementById('tag_target_weight_max').value||null,frequency_views:document.getElementById('tag_frequency_views').value||null,auto_reload:document.getElementById('tag_auto_reload').value==='1',reload_time:document.getElementById('tag_reload_time').value||null,content_width_px:document.getElementById('tag_content_width_px').value||null,content_height_px:document.getElementById('tag_content_height_px').value||null,top_offset_px:document.getElementById('tag_top_offset_px').value||null,right_offset_px:document.getElementById('tag_right_offset_px').value||null,z_index_value:document.getElementById('tag_z_index_value').value||null,is_fixed:document.getElementById('tag_is_fixed').value==='1',hide_side:document.getElementById('tag_hide_side').value||'none'};fetch('/publisher/adblocks/'+currentTagZoneData.id,{method:'PUT',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=\"csrf-token\"]').content},body:JSON.stringify(payload)}).then(async(response)=>{const data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to update tag settings.');return data;}).then((data)=>{refreshTagModal(data);const msg=document.getElementById('tagSaveMessage');msg.textContent=data.message||'Updated';msg.classList.remove('hidden');window.refreshPublisherNotifications?.();}).catch((error)=>{const msg=document.getElementById('tagSaveMessage');msg.textContent=error.message;msg.classList.remove('hidden');msg.classList.remove('text-emerald-700');msg.classList.add('text-rose-700');});}
function copyTagCode(){const textarea=document.getElementById('tag-'+activeTagTab);textarea.select();document.execCommand('copy');}
document.getElementById('adTypeSelect').addEventListener('change',()=>populatePublisherAdFormats());document.getElementById('adFormatSelect').addEventListener('change',updateZoneTypePills);populatePublisherAdFormats();populateEditFormats();
</script>
@endpush
